/* Generated by scripts/build_i18n_bundles.cjs. English is ready immediately;
   every other language is fetched only when selected. */
(() => {
  'use strict';
  const base = new URL('.', document.currentScript.src);
  const files = __LOCALE_FILES__;
  const packs = window.FLEXA_I18N = { en: __ENGLISH_PACK__ };
  const pending = new Map();
  const languages = Object.freeze(['en', ...Object.keys(files)]);
  function load(lang) {
    if (!languages.includes(lang)) return Promise.reject(new Error('Unsupported language'));
    if (packs[lang]) return Promise.resolve(packs[lang]);
    if (pending.has(lang)) return pending.get(lang);
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 15000);
    const request = fetch(new URL(files[lang], base), {signal: controller.signal})
      .then(response => {
        if (!response.ok) throw new Error('Could not load language');
        return response.json();
      })
      .then(pack => {
        if (!pack || Array.isArray(pack) || typeof pack !== 'object' ||
            !Object.keys(pack).length || Object.values(pack).some(value => typeof value !== 'string')) {
          throw new Error('Invalid language data');
        }
        packs[lang] = pack;
        return pack;
      })
      .finally(() => {clearTimeout(timeout); pending.delete(lang);});
    pending.set(lang, request);
    return request;
  }
  window.FlexaI18n = Object.freeze({load, languages});
})();
